```dart
import 'dart:collection';

class Transaction {
  String coinName;
  DateTime dateTime;
  double profitLoss; // positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  Map<String, double> coinStats = {};

  for (var transaction in transactions) {
    if (coinStats.containsKey(transaction.coinName)) {
      coinStats[transaction.coinName] += transaction.profitLoss;
    } else {
      coinStats[transaction.coinName] = transaction.profitLoss;
    }
  }

  return coinStats;
}

List<MapEntry<String, double>> sortCoinsByAverageProfitLoss(
    Map<String, double> coinStats, {bool isProfit = true}) {
  List<MapEntry<String, double>> sortedCoins = [];

  for (var entry in coinStats.entries) {
    double avg = isProfit ? entry.value / transactions.length : entry.value / transactions.length * -1;
    sortedCoins.add(MapEntry(entry.key, avg));
  }

  sortedCoins.sort((a, b) {
    if (isProfit) {
      return a.value.compareTo(b.value);
    } else {
      return b.value.compareTo(a.value);
    }
  });

  return sortedCoins;
}

