  a: {
    b: "hello",
    c: {
      d: "world"
    }
  },
  e: "goodbye"
};

const nestedKey = "a.c.d";
try {
  const result = findNestedValue(myObject, nestedKey);
  console.log(result); // Output: "world"
} catch (error) {
  console.error(error.message); // Output: No such property "a.c.d" in the object.
}
```

