```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0); // initial state is 0 degrees Celsius
  const [unit, setUnit] = useState('celsius'); // initial unit is Celsius

  const handleChange = (e) => {
    setUnit(e.target.value);
  };

  const celsiusToFahrenheit = (cel) => (cel * 1.8) + 32;
  const fahrenheitToCelsius = (fah) => ((fah - 32) * 5 / 9);

  const convertedTemperature = unit === 'celsius' ? temperature : celsiusToFahrenheit(temperature);

  return (
    <div>
      <label htmlFor="temperature">Enter temperature:</label>
      <input
        type="number"
        id="temperature"
        value={temperature}
        onChange={(e) => setTemperature(Number(e.target.value))}
      />
      <br />
      <label>
        Unit:{' '}
        <select value={unit} onChange={handleChange}>
          <option value="celsius">Celsius</option>
          <option value="fahrenheit">Fahrenheit</option>
        </select>
      </label>
      <br />
      The temperature is: {convertedTemperature} {unit}
    </div>
  );
};

export default TemperatureConverter;
```

