struct Ingredient {
    let name: String
    let taste: String
    let texture: String
}

struct Technique {
    let name: String
    let description: String
}

struct Chef {
    func createDish(ingredients: [Ingredient], techniques: [Technique]) -> Dish {
        var dishComponents: [String] = []

        // Balance of flavors
        for ingredient in ingredients {
            dishComponents.append("\(ingredient.name) adds a \(ingredient.taste) flavor.")
