        // Aroma and presentation
        dishComponents.append("Garnished with \(ingredients.last!.name), this dish presents an enticing \(techniques[1].description) aroma.")

        return Dish(components: dishComponents)
    }
}

struct Dish {
    let components: [String]
}
```

