check_numeric <- function(char_vector) {
  not_na <- which(!is.na(char_vector), arr.ind = TRUE)
  tryCatch({
    numeric_elements <- as.numeric(char_vector[not_na])
  }, error = function(e) {
    return(FALSE)
  })
  length(not_na) == length(numeric_elements)
}
```

