export const MY_CUSTOM_MIDDLEWARE = 'my-custom-middleware';

export type MyCustomMiddleware = (req: Request, res: Response, next: NextFunction) => void | Promise<void>;

export class MyCustomMiddlewareDecorator implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction, middlewareConsumer: MiddlewareConsumer): void {
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      next();
    } else {
      res.status(403).send(false);
    }
  }
}
```

This decorator is named `MyCustomMiddlewareDecorator` and implements the `NestMiddleware` interface provided by Nest.js. It also has an empty options interface `MyCustomMiddlewareOptions`. The `use` method is where the actual middleware logic goes.

2. Now, you can use the decorator in your controller or application module:

```typescript
import { Module } from '@nestjs/common';
import * as express from 'express';
import { MyController } from './my.controller';
import { MyCustomMiddlewareDecorator } from './my-custom.decorator';

@Module({
  imports: [],
  controllers: [MyController],
})
export class ApplicationModule {
  configure(consumer: MiddlewareConsumer) {
    consumer.apply(MyCustomMiddlewareDecorator).forRoutes('*');
  }
}

@Controller()
export class MyController {
  constructor() {}

  @Get()
  getHello(): string {
    return 'Hello World!';
  }
}
```

