1. First, let's create a context provider for managing the toast notifications. Create a new file called `ToastContext.js`:

```javascript
import { createContext, useState } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);
    setTimeout(() => {
      setToasts((prevToasts) => prevToasts.filter((_, i) => i !== prevToasts.length - 1));
    }, 3000); // Set duration of toast messages in milliseconds
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      <div id="toast-container" className="fixed bottom-0 right-0 p-6">
        {toasts.map((toast, index) => (
          <div key={index} className="bg-white text-gray-800 rounded-lg px-4 py-3 shadow-md w-max mb-4">{toast}</div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};
```

