public static NaiveBayesFit NaiveBayesModel(string[] trainingData, int numIterations = 10)
{
    var corpus = new DocumentTermMatrix(PreprocessData(trainingData), false);
    var learner = new MultinomialNaiveBayesLearning(new LaplaceSmoothing(1));
    var model = learner.Learn(corpus.DocumentTermMatrix);
    model.ApplyStructure(corpus.Vocabulary);
    model.Iterate(numIterations);
    return model;
}
```

