public class CO2Emission {
    private double fuelConsumption; // in gallons or liters
    private double co2EmissionsPerUnit; // in pounds or kilograms per gallon or liter

    public CO2Emission(double fuelConsumption, double co2EmissionsPerUnit) {
        this.fuelConsumption = fuelConsumption;
        this.co2EmissionsPerUnit = co2EmissionsPerUnit;
    }

    public double getCo2Emissions() {
        return this.co2EmissionsPerUnit * this.fuelConsumption;
    }
}

// Usage example:
