 Here's the code for the `RedisClient.js` file inside the `utils` folder:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();

    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          return reject(err);
        }

        resolve(value);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          return reject(err);
        }

        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) {
          return reject(err);
        }

        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

This code defines the `RedisClient` class with the required functions and exports both the class and an instance named `redisClient`. The constructor initializes the Redis client and sets up an error handler. The methods `get`, `set`, and `del` are asynchronous and make use of Promises to handle the Redis responses. Additionally, the `isAlive` method checks whether the connection to Redis is active or not.

