List<string> GenerateEthicalConcerns(int numberOfConcerns)
{
    List<string> randomConcerns = new List<string>();
    HashSet<string> usedConcerns = new HashSet<string>(ethicalConcerns);

    while (randomConcerns.Count < numberOfConcerns)
    {
        string randomConcern = usedConcerns.ElementAt(new Random().Next(usedConcerns.Count));
        randomConcerns.Add(randomConcern);
        usedConcerns.Remove(randomConcern);
