 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Create a slice of specific negative words.
2. Tokenize the input sentence into individual words.
3. Iterate through each token (word) in the tokenized sentence.
4. Check if the current token is a negative word or "not".
5. If the current token is a negative word, store its index in a map with the word as the key for easier lookup.
6. After iterating through all tokens, check for the presence of a second negative word or double "not" in the sentence.

Here's the Go code implementing the above steps:

```go
package main

import (
	"fmt"
	"strings"
)

// List of negative words
var negatives = []string{"isn't", "am not", "are not", "doesn't", "don't", "have not", "haven't", "hasn't", "had not", "won't", "wouldn't", "can't", "couldn't", "shall not", "shouldn't", "may not", "might not", "must not"}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	tokens := strings.Fields(sentence) // Split sentence into words using spaces as delimiter
	negations := make(map[string]int)

	for i, token := range tokens {
		if isNegativeWord(token) || token == "not" && i > 0 && negations[tokens[i-1]] > 0 {
			fmt.Println("Double Negative Detected!")
			return
		}
		if isNegativeWord(token) {
			negations[token]++
		}
	}

	fmt.Println("No Double Negative found.")
}

// Function to check if a word is a negative word
func isNegativeWord(word string) bool {
	for _, negative := range negatives {
		if strings.EqualFold(negative, word) {
			return true
		}
	}

